import{_ as e,c as r,o as i,ah as n}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"54、【歸妹】 兌下震上","description":"溫公易說 - 54、【歸妹】 兌下震上","frontmatter":{"title":"54、【歸妹】 兌下震上","description":"溫公易說 - 54、【歸妹】 兌下震上"},"headers":[],"relativePath":"classics/wengong/055.md","filePath":"classics/wengong/055.md"}'),l={name:"classics/wengong/055.md"};function t(h,a,s,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[n('<h1 id="_54、【歸妹】-兌下震上" tabindex="-1">54、【歸妹】 兌下震上 <a class="header-anchor" href="#_54、【歸妹】-兌下震上" aria-label="Permalink to “54、【歸妹】 兌下震上”">​</a></h1><h3 id="彖曰-歸妹-天地之大義也。天地不交而萬物不興-歸妹人之終始也。說以動-所歸妹也。徵兇-位不當也。無攸利-柔乘剛也。" tabindex="-1">彖曰：歸妹，天地之大義也。天地不交而萬物不興，歸妹人之終始也。說以動，所歸妹也。徵兇，位不當也。無攸利，柔乘剛也。 <a class="header-anchor" href="#彖曰-歸妹-天地之大義也。天地不交而萬物不興-歸妹人之終始也。說以動-所歸妹也。徵兇-位不當也。無攸利-柔乘剛也。" aria-label="Permalink to “彖曰：歸妹，天地之大義也。天地不交而萬物不興，歸妹人之終始也。說以動，所歸妹也。徵兇，位不當也。無攸利，柔乘剛也。”">​</a></h3><h3 id="象曰-澤上有雷-歸妹。君子以永終知敝。" tabindex="-1">象曰：澤上有雷，歸妹。君子以永終知敝。 <a class="header-anchor" href="#象曰-澤上有雷-歸妹。君子以永終知敝。" aria-label="Permalink to “象曰：澤上有雷，歸妹。君子以永終知敝。”">​</a></h3><h3 id="初九-歸妹以娣-跛能履-徵吉-象曰-歸妹以娣-以恆也。跛能履-吉-相承也。" tabindex="-1">初九：歸妹以娣，跛能履，徵吉 象曰：歸妹以娣，以恆也。跛能履，吉，相承也。 <a class="header-anchor" href="#初九-歸妹以娣-跛能履-徵吉-象曰-歸妹以娣-以恆也。跛能履-吉-相承也。" aria-label="Permalink to “初九：歸妹以娣，跛能履，徵吉 象曰：歸妹以娣，以恆也。跛能履，吉，相承也。”">​</a></h3><p>不正而合，是以跛也。</p><h3 id="九二-眇能視-利幽人之貞-象曰-利幽人之貞-未變常也。" tabindex="-1">九二：眇能視，利幽人之貞 象曰：利幽人之貞，未變常也。 <a class="header-anchor" href="#九二-眇能視-利幽人之貞-象曰-利幽人之貞-未變常也。" aria-label="Permalink to “九二：眇能視，利幽人之貞 象曰：利幽人之貞，未變常也。”">​</a></h3><h3 id="六三-歸妹以須-反歸以娣-象曰-歸妹以須-未當也。" tabindex="-1">六三：歸妹以須，反歸以娣 象曰：歸妹以須，未當也。 <a class="header-anchor" href="#六三-歸妹以須-反歸以娣-象曰-歸妹以須-未當也。" aria-label="Permalink to “六三：歸妹以須，反歸以娣 象曰：歸妹以須，未當也。”">​</a></h3><h3 id="九四-歸妹愆期-遲歸有時-象曰-愆期之志-有待而行也。" tabindex="-1">九四：歸妹愆期，遲歸有時 象曰：愆期之志，有待而行也。 <a class="header-anchor" href="#九四-歸妹愆期-遲歸有時-象曰-愆期之志-有待而行也。" aria-label="Permalink to “九四：歸妹愆期，遲歸有時 象曰：愆期之志，有待而行也。”">​</a></h3><h3 id="六五-帝乙歸妹-其君之袂不如其娣之袂良-月幾望-吉-象曰-帝乙歸妹-不如其娣之袂良也。其位在中-以貴行也。" tabindex="-1">六五：帝乙歸妹，其君之袂不如其娣之袂良，月幾望，吉 象曰：帝乙歸妹，不如其娣之袂良也。其位在中，以貴行也。 <a class="header-anchor" href="#六五-帝乙歸妹-其君之袂不如其娣之袂良-月幾望-吉-象曰-帝乙歸妹-不如其娣之袂良也。其位在中-以貴行也。" aria-label="Permalink to “六五：帝乙歸妹，其君之袂不如其娣之袂良，月幾望，吉 象曰：帝乙歸妹，不如其娣之袂良也。其位在中，以貴行也。”">​</a></h3><h3 id="上六-女承筐-無實-士刲羊無血-無攸利-象曰-上六無實-承虛筐也。" tabindex="-1">上六：女承筐，無實，士刲羊無血，無攸利 象曰：上六無實，承虛筐也。 <a class="header-anchor" href="#上六-女承筐-無實-士刲羊無血-無攸利-象曰-上六無實-承虛筐也。" aria-label="Permalink to “上六：女承筐，無實，士刲羊無血，無攸利 象曰：上六無實，承虛筐也。”">​</a></h3>',10)])])}const m=e(l,[["render",t]]);export{b as __pageData,m as default};
